<?php require_once '../config.php'; requireLogin(); header('Content-Type: application/json; charset=utf-8'); if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit;}try{$id=(int)($_POST['word_id']??0);$correct=($_POST['correct']??'0')==='1';if(!$id)throw new RuntimeException('واژه نامعتبر است');$r=sb_rpc('review_word',['p_word_id'=>$id,'p_correct'=>$correct],getAccessToken());echo json_encode(is_array($r)?$r:['success'=>true],JSON_UNESCAPED_UNICODE);}catch(Throwable $e){http_response_code(400);echo json_encode(['success'=>false,'error'=>sb_error_message($e)],JSON_UNESCAPED_UNICODE);}